html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value is not none else "" }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form .ref td { font-size: 10.5px; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; }
.lpl-form .sign { border: none; padding: 6px 0 0; }
.lpl-form .narrow { width: 9%; text-align: center; }
.lpl-form .scores td { text-align: center; font-weight: bold; }
</style>
<div class="lpl-form">
<h3>Performance Improvement Plan</h3>
<table>
<tr><th style="width:18%">Employee</th><td>{{ v(doc.employee_name) }}</td>
<th style="width:14%">Designation</th><td>{{ v(doc.designation) }}</td></tr>
<tr><th>Department</th><td>{{ v(doc.department) }}</td><th>Plant</th><td>{{ v(doc.branch) }}</td></tr>
<tr><th>Supervisor</th><td>{{ v(frappe.db.get_value("Employee", doc.supervisor, "employee_name")
  if doc.supervisor else "") }}</td>
<th>Appraisal Score</th><td>{{ num(doc.appraisal_score) }}%</td></tr>
<tr><th>Period</th><td>{{ day(doc.start_date) }} to {{ day(doc.end_date) }}</td>
<th>Status</th><td>{{ v(doc.status) }}</td></tr>
</table>
<p><b>Why this plan:</b> {{ v(doc.reason) }}</p>

<h4>What must improve</h4>
<table>
<tr><th style="width:4%">#</th><th>Area to improve</th><th>Expected standard</th><th>Support from the company</th>
<th>How it is measured</th><th style="width:11%">Review date</th><th style="width:10%">Progress</th></tr>
{%- for row in doc.objectives %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.area) }}</td><td>{{ v(row.expected_standard) }}</td>
<td>{{ v(row.support) }}</td><td>{{ v(row.measure) }}</td><td>{{ day(row.review_date) }}</td>
<td>{{ v(row.progress) }}</td></tr>
{%- endfor %}
</table>

{%- if doc.reviews %}
<h4>Review meetings</h4>
<table>
<tr><th style="width:12%">Date</th><th style="width:24%">Present</th><th style="width:12%">Progress</th>
<th>What was agreed</th></tr>
{%- for row in doc.reviews %}
<tr><td>{{ day(row.reviewed_on) }}</td><td>{{ v(row.attendees) }}</td><td>{{ v(row.progress) }}</td>
<td>{{ v(row.notes) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}

{%- if doc.outcome %}
<h4>Outcome</h4>
<p><b>{{ v(doc.outcome) }}</b>{% if doc.new_end_date %} &mdash; extended to {{ day(doc.new_end_date) }}{% endif %}</p>
<div class="rule">{{ v(doc.outcome_remarks) }}</div>
{%- endif %}

<h4>Agreement</h4>
<p>We agree to this plan and to the support and the standards set out in it.</p>
<table><tr class="sign">
<td class="sign">Employee {{ v(doc.employee_name) }} &hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;
Date {{ day(doc.employee_agreed_on) }}</td></tr>
<tr><td class="sign">Supervisor &hellip;&hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;
Date {{ day(doc.supervisor_agreed_on) }}</td></tr>
<tr><td class="sign">Human Resources &hellip;&hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;
Date {{ day(doc.closed_on) }}</td></tr></table>
</div>
